import{_ as e,o as t,c as s,ae as n}from"./chunks/framework.Dh1jimFm.js";const m=JSON.parse('{"title":"CAT Tool Integration Overview","description":"","frontmatter":{},"headers":[],"relativePath":"cat-tools/overview.md","filePath":"cat-tools/overview.md"}'),o={name:"cat-tools/overview.md"};function r(l,a,i,p,d,c){return t(),s("div",null,a[0]||(a[0]=[n(`<h1 id="cat-tool-integration-overview" tabindex="-1">CAT Tool Integration Overview <a class="header-anchor" href="#cat-tool-integration-overview" aria-label="Permalink to &quot;CAT Tool Integration Overview&quot;">​</a></h1><p>Supervertaler is designed to work alongside professional CAT (Computer-Assisted Translation) tools, not replace them. Use it as a <strong>companion tool</strong> for AI-powered translation within your existing workflow.</p><h2 id="supported-cat-tools" tabindex="-1">Supported CAT Tools <a class="header-anchor" href="#supported-cat-tools" aria-label="Permalink to &quot;Supported CAT Tools&quot;">​</a></h2><table tabindex="0"><thead><tr><th>CAT Tool</th><th>Import Format</th><th>Export Format</th></tr></thead><tbody><tr><td><strong>memoQ</strong></td><td>Bilingual DOCX, XLIFF</td><td>Bilingual DOCX</td></tr><tr><td><strong>Trados Studio</strong></td><td>SDLPPX packages</td><td>SDLRPX return packages</td></tr><tr><td><strong>Phrase (Memsource)</strong></td><td>Bilingual DOCX</td><td>Bilingual DOCX</td></tr><tr><td><strong>CafeTran Espresso</strong></td><td>Bilingual table DOCX</td><td>Bilingual table DOCX</td></tr></tbody></table><h2 id="why-use-supervertaler-with-cat-tools" tabindex="-1">Why Use Supervertaler with CAT Tools? <a class="header-anchor" href="#why-use-supervertaler-with-cat-tools" aria-label="Permalink to &quot;Why Use Supervertaler with CAT Tools?&quot;">​</a></h2><h3 id="ai-translation-power" tabindex="-1">AI Translation Power <a class="header-anchor" href="#ai-translation-power" aria-label="Permalink to &quot;AI Translation Power&quot;">​</a></h3><p>CAT tools have limited AI integration. Supervertaler lets you:</p><ul><li>Use multiple LLM providers (GPT-4, Claude, Gemini)</li><li>Create custom translation prompts</li><li>Batch translate with context awareness</li><li>Leverage semantic TM search (Supermemory)</li></ul><h3 id="workflow-flexibility" tabindex="-1">Workflow Flexibility <a class="header-anchor" href="#workflow-flexibility" aria-label="Permalink to &quot;Workflow Flexibility&quot;">​</a></h3><ul><li>Translate offline with Ollama</li><li>Work on files while others are locked in the CAT tool</li><li>Quick review and post-editing without heavy software</li></ul><h2 id="typical-workflow" tabindex="-1">Typical Workflow <a class="header-anchor" href="#typical-workflow" aria-label="Permalink to &quot;Typical Workflow&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌─────────────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│                    YOUR CAT TOOL                            │</span></span>
<span class="line"><span>│  (memoQ, Trados, Phrase, CafeTran)                         │</span></span>
<span class="line"><span>│                                                             │</span></span>
<span class="line"><span>│  1. Receive project from client                            │</span></span>
<span class="line"><span>│  2. Set up TM, termbases in CAT tool                       │</span></span>
<span class="line"><span>│  3. Export bilingual file or package                       │</span></span>
<span class="line"><span>└─────────────────────────────────────────────────────────────┘</span></span>
<span class="line"><span>                            ↓</span></span>
<span class="line"><span>┌─────────────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│                    SUPERVERTALER                            │</span></span>
<span class="line"><span>│                                                             │</span></span>
<span class="line"><span>│  4. Import bilingual file                                  │</span></span>
<span class="line"><span>│  5. AI translate + post-edit                               │</span></span>
<span class="line"><span>│  6. Use Superlookup for research                           │</span></span>
<span class="line"><span>│  7. Export bilingual file                                  │</span></span>
<span class="line"><span>└─────────────────────────────────────────────────────────────┘</span></span>
<span class="line"><span>                            ↓</span></span>
<span class="line"><span>┌─────────────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│                    YOUR CAT TOOL                            │</span></span>
<span class="line"><span>│                                                             │</span></span>
<span class="line"><span>│  8. Import translations back                               │</span></span>
<span class="line"><span>│  9. Run QA checks                                          │</span></span>
<span class="line"><span>│  10. Deliver to client                                     │</span></span>
<span class="line"><span>└─────────────────────────────────────────────────────────────┘</span></span></code></pre></div><h2 id="key-concepts" tabindex="-1">Key Concepts <a class="header-anchor" href="#key-concepts" aria-label="Permalink to &quot;Key Concepts&quot;">​</a></h2><h3 id="preserving-formatting" tabindex="-1">Preserving Formatting <a class="header-anchor" href="#preserving-formatting" aria-label="Permalink to &quot;Preserving Formatting&quot;">​</a></h3><p>Supervertaler preserves CAT tool formatting tags:</p><ul><li>memoQ: <code>{1}</code>, <code>[2}</code>, <code>{MQ}</code> inline tags</li><li>Trados: <code>&lt;1&gt;</code>, <code>&lt;/1&gt;</code> numbered tags</li><li>Tags are highlighted in the grid for visibility</li></ul><h3 id="segment-status" tabindex="-1">Segment Status <a class="header-anchor" href="#segment-status" aria-label="Permalink to &quot;Segment Status&quot;">​</a></h3><p>Segment statuses map between tools:</p><ul><li><strong>Draft</strong> → Trados <em>Draft</em> / memoQ <em>Edited</em></li><li><strong>Confirmed</strong> → Trados <em>Translated</em> ✓ / memoQ <em>Confirmed</em></li><li><strong>Approved</strong> → Trados <em>Sign-off Approved</em> / memoQ <em>Reviewer 2 confirmed</em></li></ul><p>See <a href="./../editor/segment-statuses.html">Segment Statuses</a> for the full reference.</p><h3 id="round-trip-compatibility" tabindex="-1">Round-Trip Compatibility <a class="header-anchor" href="#round-trip-compatibility" aria-label="Permalink to &quot;Round-Trip Compatibility&quot;">​</a></h3><p>Files exported from Supervertaler can be imported back into the CAT tool with:</p><ul><li>All translations preserved</li><li>Status information maintained</li><li>Formatting intact</li></ul><h2 id="choosing-the-right-workflow" tabindex="-1">Choosing the Right Workflow <a class="header-anchor" href="#choosing-the-right-workflow" aria-label="Permalink to &quot;Choosing the Right Workflow&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Scenario</th><th>Recommended Workflow</th></tr></thead><tbody><tr><td><strong>Full project in memoQ</strong></td><td><a href="./memoq.html">memoQ Bilingual DOCX</a></td></tr><tr><td><strong>Trados Studio package</strong></td><td><a href="./trados.html">SDLPPX/SDLRPX</a></td></tr><tr><td><strong>Phrase/Memsource project</strong></td><td><a href="./phrase.html">Phrase Bilingual DOCX</a></td></tr><tr><td><strong>CafeTran external view</strong></td><td><a href="./cafetran.html">CafeTran DOCX</a></td></tr><tr><td><strong>Standalone DOCX</strong></td><td>Direct import, no CAT tool needed</td></tr></tbody></table><hr><h2 id="tool-specific-guides" tabindex="-1">Tool-Specific Guides <a class="header-anchor" href="#tool-specific-guides" aria-label="Permalink to &quot;Tool-Specific Guides&quot;">​</a></h2><div class="sv-cards"><a class="sv-card" href="/cat-tools/memoq"><span class="sv-card-title">memoQ</span><span class="sv-card-desc">memoQ workflow guide →</span></a><a class="sv-card" href="/cat-tools/trados"><span class="sv-card-title">Trados Studio</span><span class="sv-card-desc">Trados workflow guide →</span></a><a class="sv-card" href="/cat-tools/phrase"><span class="sv-card-title">Phrase</span><span class="sv-card-desc">Phrase workflow guide →</span></a><a class="sv-card" href="/cat-tools/cafetran"><span class="sv-card-title">CafeTran</span><span class="sv-card-desc">CafeTran workflow guide →</span></a></div>`,28)]))}const u=e(o,[["render",r]]);export{m as __pageData,u as default};
